function setTable(table, rows) {
  localStorage.setItem('bwanali_' + table, JSON.stringify(rows));
  window.dispatchEvent(new CustomEvent('db-change', { detail: { table } }));
}

// Seed once
if (!localStorage.getItem('bwanali_seeded')) {
  setTable('stores', [{ id: 'store-1', name: 'Demo Store', subscription_status: 'trialing', trial_started_at: new Date().toISOString(), subscription_plan: 'monthly', locked: false }]);
  setTable('staff', [{ id: 'staff-1', store_id: 'store-1', full_name: 'Admin Demo', email: 'admin@demo.com', role: 'admin', pin_code: '1234', is_active: true }]);
