    catch: (fn) => safe(val),
  };
  if (val !== null && typeof val === 'object') {
    return new Proxy(val, {
      get(target, prop) {
        if (prop === 'then') return obj.then;
        if (prop === 'catch') return obj.catch;
        return target[prop];
      }
    });
  }
  return obj;
}

// Query builder that always returns a catch-safe object
function query(table) {
  const ctx = {
    table,
    filters: [],
    limit: null,
    single: false,
    orderCol: null,
    orderAsc: true,
  };

  const builder = {
    select: () => builder,
    eq: (col, val) => { ctx.filters.push({ type: 'eq', col, val }); return builder; },
    gte: (col, val) => { ctx.filters.push({ type: 'gte', col, val }); return builder; },
    lte: (col, val) => { ctx.filters.push({ type: 'lte', col, val }); return builder; },
    not: (col, val) => { ctx.filters.push({ type: 'not', col, val }); return builder; },
    is: (col, val) => { ctx.filters.push({ type: 'is', col, val }); return builder; },
    in: (col, vals) => { ctx.filters.push({ type: 'in', col, vals }); return builder; },
    order: (col, opts) => { ctx.orderCol = col; ctx.orderAsc = opts?.ascending !== false; return builder; },
    limit: (n) => { ctx.limit = n; return builder; },
    single: () => { ctx.single = true; return builder; },
    maybeSingle: () => { ctx.single = true; return builder; },
    then: (resolve) => {
      let rows = getTable(ctx.table);
      rows = rows.filter(r => ctx.filters.every(f => {
        try {
          if (f.type === 'eq') return r[f.col] === f.val;
          if (f.type === 'gte') return new Date(r[f.col]) >= new Date(f.val);
          if (f.type === 'lte') return new Date(r[f.col]) <= new Date(f.val);
          if (f.type === 'not') return r[f.col] !== f.val;
          if (f.type === 'is') return r[f.col] === null || r[f.col] === undefined;
          if (f.type === 'in') return f.vals.includes(r[f.col]);
          return true;
        } catch { return false; }
      }));
      if (ctx.orderCol) rows.sort((a, b) => (a[ctx.orderCol] > b[ctx.orderCol] ? 1 : -1) * (ctx.orderAsc ? 1 : -1));
      if (ctx.limit !== null) rows = rows.slice(0, ctx.limit);
      resolve(ctx.single ? { data: rows[0] || null, error: null } : { data: rows, error: null });
    },
    catch: (fn) => builder,
  };
  return safe(builder);
}

// mutation helpers
function dbInsert(table, payload) {
  const rows = getTable(table);
  const arr = Array.isArray(payload) ? payload : [payload];
  const newRows = arr.map(d => {
    const base = { id: id(), ...d };
    if (table === 'sales' && !base.invoice_number) base.invoice_number = '' + (rows.length + 1);
    return base;
  });
  setTable(table, [...rows, ...newRows]);
  const res = safe({ data: newRows, error: null });
  res.select = () => safe({ data: newRows, error: null });
  res.single = () => safe({ data: newRows[0] || null, error: null });
  return res;
}

function dbUpdate(table, data, filters) {
  const rows = getTable(table);
  const updated = rows.map(r => filters.every(f => r[f.col] === f.val) ? { ...r, ...data } : r);
  setTable(table, updated);
  return safe({ error: null });
}

function dbDelete(table, filters) {
  const rows = getTable(table);
  const remaining = rows.filter(r => !filters.every(f => r[f.col] === f.val));
  setTable(table, remaining);
  return safe({ error: null });
}

function dbUpsert(table, payload) {
  const rows = getTable(table);
  const arr = Array.isArray(payload) ? payload : [payload];
  arr.forEach(d => {
    const idx = rows.findIndex(r => r.id === d.id);
    if (idx >= 0) rows[idx] = d;
    else rows.push({ id: id(), ...d });
  });
  setTable(table, rows);
  return safe({ error: null });
}

export const supabase = safe({
  from: (table) => safe({
    select: (cols, opts) => {
      const q = query(table);
      if (opts?.count === 'exact') {
        q._count = true;
        q._head = opts.head || false;
      }
      return q;
    },
    insert: (data) => dbInsert(table, data),
    update: (data) => safe({
      eq: (col, val) => dbUpdate(table, data, [{ type: 'eq', col, val }]),
      in: (col, vals) => dbUpdate(table, data, [{ type: 'in', col, vals }]),
    }),
    delete: () => safe({
      eq: (col, val) => dbDelete(table, [{ type: 'eq', col, val }]),
    }),
    upsert: (data) => dbUpsert(table, data),
  }),
  auth: safe({
    signInWithPassword: async ({ email, password }) => {
      const staff = getTable('staff');
      const user = staff.find(u => u.email === email && u.pin_code === password);
      if (!user) return { error: { message: 'Invalid credentials' } };
      localStorage.setItem('local_user', JSON.stringify(user));
      return { data: { user }, error: null };
    },
    signOut: async () => { localStorage.removeItem('local_user'); return { error: null }; },
    getSession: async () => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      return { data: { session: user ? { user, access_token: 'offline', refresh_token: 'offline' } : null } };
    },
    onAuthStateChange: (cb) => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      setTimeout(() => cb('SIGNED_IN', { user }), 10);
      return { data: { subscription: { unsubscribe: () => {} } } };
    },
    setSession: async () => ({ error: null }),
    signUp: async ({ email, password, options }) => {
      const staff = getTable('staff');
      const newUser = { id: id(), email, pin_code: password, full_name: options?.data?.full_name || 'New User', role: 'cashier', is_active: true, store_id: null };
      setTable('staff', [...staff, newUser]);
      return { data: { user: newUser }, error: null };
    },
  }),
  storage: safe({
    from: () => safe({
      upload: async () => ({ error: null }),
      getPublicUrl: () => ({ data: { publicUrl: '' } }),
    }),
  }),
  rpc: () => safe({ error: null }),
});
